window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-794f3df4a8bb388c"]={"versions": [{"id": "FIG-794f3df4a8bb388c", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Informelles Block- und Datenflussdiagramm (Architekturübersicht / Functional Flow Block Diagram) zur Darstellung der funktionalen Allokation und des Kontrollflusses.</li>\n<li><strong>Funktionale Einordnung:</strong> AUTOSAR Adaptive Platform (R20-11), Spezifikation <em>ASWS Health Monitoring</em> (gemäß <code>RS_HM_09304</code> – <em>Health information exchange between platforms</em>).</li>\n<li><strong>Technischer Zweck:</strong> Definition der vertikalen und horizontalen Interaktionsmuster zwischen lokalen Plattform-Überwachungsinstanzen (Classic Platform WdgM/BswM vs. Adaptive Platform PHM) und einer übergeordneten, plattformübergreifenden Instanz (<strong>System Health Manager</strong>, SHM). Das Diagramm visualisiert die Trennung von lokaler Fehlerbehandlung (Local Recovery) und koordinierter Gesamtsystem-Reaktion (System Recovery).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>System Health Manager (SHM):</strong></li>\n<li>Übergeordnete Koordinationsinstanz (zentralisiert oder verteilt ausgeführt).</li>\n<li>Kernfunktion: <em>Determination of Health Indicator(s)</em> – Aggregation und Korrelation plattformspezifischer Gesundheitsindikatoren zu einem konsistenten Systemzustand.</li>\n<li><strong>Adaptive Platform (AP-Instanz):</strong></li>\n<li>Implementiert durch den <em>Platform Health Management</em> (PHM) Dämon und <em>State Management</em> (SM).</li>\n<li>Interne Funktionsblöcke:</li>\n<li><em>Execution of Supervision Functions:</em> Alive-, Deadline- und Logical Supervision über Checkpoints (<code>ara::phm</code>).</li>\n<li><em>Determination of Supervision Status:</em> Aggregation lokaler Checkpoint-Ergebnisse zu <em>Supervision Status</em> / <em>Health Channel Status</em>.</li>\n<li><em>Local Platform Recovery Action:</em> Autonome plattforminterne Aktionen (z. B. Prozess-Neustart via Execution Management <code>ara::exec</code>).</li>\n<li><em>Execution of system Recovery Action:</em> Ausführung von Befehlen des SHM (z. B. Function Group State Transitionen).</li>\n<li><strong>Classic Platform (CP-Instanz):</strong></li>\n<li>Implementiert durch <em>Watchdog Manager</em> (<code>WdgM</code>), <em>Basic Software Manager</em> (<code>BswM</code>) und <code>Dem</code>.</li>\n<li>Interne Funktionsblöcke analog zur AP:</li>\n<li><em>Execution of Supervision Functions:</em> Alive-, Deadline- und Logical-Supervision von Supervised Entities (<code>SE</code>).</li>\n<li><em>Determination of Supervision Status:</em> Lokaler/globaler WdgM-Status (<code>WDGM_GLOBAL_STATUS_*</code>).</li>\n<li><em>Local Platform Recovery Action:</em> Lokale Eskalation (z. B. Watchdog-Reset über <code>WdgIf</code>/<code>Wdg</code>, Partition-Restart, BswM-Aktionen).</li>\n<li><em>Execution of system Recovery Action:</em> Koordinierte Degradierung (z. B. ECU-Zustandswechsel in <code>EcuM</code>/<code>BswM</code>).</li>\n<li><strong>Schnittstellen & Datenstrukturen:</strong></li>\n<li><strong>Uplink (Plattform $\\rightarrow$ SHM):</strong> <em>Health Indicator + additional Payload</em></li>\n<li>Übermittlung via fahrzeuginterner Kommunikation (z. B. SOME/IP Events, Ethernet, CAN-FD).</li>\n<li>Signalisiert den lokalen Gesundheitsstatus zuzüglich Kontextdaten (z. B. ausgefallene Entity-ID, Fehlercode, Fehlertoleranzzeit/FTTI-Restbudget).</li>\n<li><strong>Downlink (SHM $\\rightarrow$ Plattform):</strong> <em>Health Indicator</em> (bzw. System Action Command)</li>\n<li>Übermittlung an AP und CP zur Einleitung synchronisierter Degradierungsmodi (Fail-Operational / Fail-Safe Safe States).</li>\n<li><strong>Peer-Schnittstellen (gestrichelt):</strong></li>\n<li>Inter-SHM-Kommunikation (<em>Other System Health Manager(s)</em>) und generische Nicht-AUTOSAR-Domänen (<em>Other platform(s)</em>, z. B. Linux/QNX-Host-OS oder Hypervisor Health).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Lokale Erfassung (Zyklisch / Eventbasiert):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Supervised Entities (SWCs auf CP, Prozesse auf AP) melden Checkpoint-Erreichungen an die lokale Überwachung (<code>WdgM</code> bzw. <code>ara::phm</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Lokale Zustandsbewertung & Sofortmaßnahme:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bestimmung des lokalen Status (<em>Determination of Supervision Status</em>).</li>\n<li>Bei Verletzung: Triggerung von <em>Local Platform Recovery Action</em>. Auf AP: Benachrichtigung an <code>Execution Management</code> zum Prozess-Restart; auf CP: BswM-Regelausführung oder lokaler Watchdog-Timeout.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Meldung an Gesamtsystem (Asynchroner Uplink):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Parallel oder nach Scheitern der lokalen Recovery wird ein <em>Health Indicator + additional Payload</em> über das Kommunikationsnetzwerk an den <em>System Health Manager</em> serialisiert und versendet.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zentrale Systementscheidung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der SHM bewertet alle eingehenden Indikatoren (<em>Determination of Health Indicator(s)</em>) und optionalen Zustände weiterer SHM-Instanzen/Plattformen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>System-Recovery-Kaskade (Downlink Trigger):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>SHM sendet den resultierenden aggregierten <em>Health Indicator</em> / Recovery-Befehl an die betroffenen Plattformen (AP und CP).</li>\n<li>Beide Plattformen triggern synchronisiert ihre jeweiligen Mechanismen zur Systemwiederherstellung (<em>Execution of system Recovery Action</em>), z. B. Umschalten in ein redundantes Fallback-Netzwerk, Degradieren der Fahrfunktion oder koordinierter Systemneustart.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>AP-Entwickler (<code>ara::phm</code>, <code>ara::exec</code>, <code>ara::sm</code>):</strong></li>\n<li><strong>API & Konfiguration:</strong> Checkpoints müssen nach ASWS PHM präzise modelliert werden. Reicht ein lokaler Recovery-Versuch (z. B. <code>RestartProcess</code>) nicht aus oder führt zu Grenzwertüberschreitungen, muss der <code>PHM</code> so konfiguriert sein, dass über AraCom ein Health-Event an den SHM emittiert wird.</li>\n<li>Das <em>State Management</em> muss auf SHM-Payloads reagieren können, um Function Group Transitions (z. B. <code>OffSafe</code>) anzusteuern.</li>\n<li><strong>CP-Entwickler (<code>WdgM</code>, <code>BswM</code>, <code>Com</code>):</strong></li>\n<li><strong>API & Stack-Routing:</strong> Der WdgM-Status (<code>WdgM_GetGlobalStatus</code>) muss über den BswM oder eine System-SWC periodisch/ereignisgesteuert via RTE an den Kommunikationsstack (<code>PduR</code>/<code>SomeIpXf</code>/<code>Com</code>) geroutet werden, um als Payload für den SHM bereitgestellt zu werden.</li>\n<li>System Recovery Actions erfordern vorbereitete BswM-Regelwerke (Action Lists für Shutdown/Reset/Mode Switches via <code>EcuM</code>).</li>\n<li><strong>Systemarchitektur & ASIL-Dekompensation (ISO 26262):</strong></li>\n<li>Die Latenz des Austauschs (<em>Health Indicator + Payload</em>) über Bussysteme begrenzt die erreichbare FTTI (Fault Tolerant Time Interval) für gesamtsystemische Reaktionen.</li>\n<li>Für sicherheitskritische System Recovery Actions müssen End-to-End-Sicherungsmechanismen (E2E-Profile auf Uplink/Downlink) und deterministische Kommunikationskanäle (TSN / deterministisches CAN-FD) verbindlich ausgelegt werden.</li>\n</ul>"}, {"id": "FIG-16b052a715261367", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Informelles Block- und Datenflussdiagramm (Architekturübersicht / Functional Flow Block Diagram) zur Darstellung der funktionalen Allokation und des Kontrollflusses.</li>\n<li><strong>Funktionale Einordnung:</strong> AUTOSAR Adaptive Platform (R20-11), Spezifikation <em>ASWS Health Monitoring</em> (gemäß <code>RS_HM_09304</code> – <em>Health information exchange between platforms</em>).</li>\n<li><strong>Technischer Zweck:</strong> Definition der vertikalen und horizontalen Interaktionsmuster zwischen lokalen Plattform-Überwachungsinstanzen (Classic Platform WdgM/BswM vs. Adaptive Platform PHM) und einer übergeordneten, plattformübergreifenden Instanz (<strong>System Health Manager</strong>, SHM). Das Diagramm visualisiert die Trennung von lokaler Fehlerbehandlung (Local Recovery) und koordinierter Gesamtsystem-Reaktion (System Recovery).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>System Health Monitor (SHM):</strong></li>\n<li>Übergeordnete Koordinationsinstanz (zentralisiert oder verteilt ausgeführt).</li>\n<li>Kernfunktion: <em>Determination of Health Indicator(s)</em> – Aggregation und Korrelation plattformspezifischer Gesundheitsindikatoren zu einem konsistenten Systemzustand.</li>\n<li><strong>Adaptive Platform (AP-Instanz):</strong></li>\n<li>Implementiert durch den <em>Platform Health Management</em> (PHM) Dämon und <em>State Management</em> (SM).</li>\n<li>Interne Funktionsblöcke:</li>\n<li><em>Execution of Supervision Functions:</em> Alive-, Deadline- und Logical Supervision über Checkpoints (<code>ara::phm</code>).</li>\n<li><em>Determination of Supervision Status:</em> Aggregation lokaler Checkpoint-Ergebnisse zu <em>Supervision Status</em> / <em>Health Channel Status</em>.</li>\n<li><em>Local Platform Recovery Action:</em> Autonome plattforminterne Aktionen (z. B. Prozess-Neustart via Execution Management <code>ara::exec</code>).</li>\n<li><em>Execution system Recovery Action:</em> Ausführung von Befehlen des SHM (z. B. Function Group State Transitionen).</li>\n<li><strong>Classic Platform (CP-Instanz):</strong></li>\n<li>Implementiert durch <em>Watchdog Manager</em> (<code>WdgM</code>), <em>Basic Software Manager</em> (<code>BswM</code>) und <code>Dem</code>.</li>\n<li>Interne Funktionsblöcke analog zur AP:</li>\n<li><em>Execution of Supervision Functions:</em> Alive-, Deadline- und Logical-Supervision von Supervised Entities (<code>SE</code>).</li>\n<li><em>Determination of Supervision Status:</em> Lokaler/globaler WdgM-Status (<code>WDGM_GLOBAL_STATUS_*</code>).</li>\n<li><em>Local Platform Recovery Action:</em> Lokale Eskalation (z. B. Watchdog-Reset über <code>WdgIf</code>/<code>Wdg</code>, Partition-Restart, BswM-Aktionen).</li>\n<li><em>Execution system Recovery Action:</em> Koordinierte Degradierung (z. B. ECU-Zustandswechsel in <code>EcuM</code>/<code>BswM</code>).</li>\n<li><strong>Schnittstellen & Datenstrukturen:</strong></li>\n<li><strong>Uplink (Plattform $\\rightarrow$ SHM):</strong> <em>Health Indicator + HealthInfo</em></li>\n<li>Übermittlung via fahrzeuginterner Kommunikation (z. B. SOME/IP Events, Ethernet, CAN-FD).</li>\n<li>Signalisiert den lokalen Gesundheitsstatus zuzüglich standardisierter Zusatzinformationen (<code>HealthInfo</code>, z. B. ausgefallene Entity-ID, Fehlercode, Fehlertoleranzzeit/FTTI-Restbudget).</li>\n<li><strong>Downlink (SHM $\\rightarrow$ Plattform):</strong> <em>Health Indicator</em> (bzw. System Action Command)</li>\n<li>Übermittlung an AP und CP zur Einleitung synchronisierter Degradierungsmodi (Fail-Operational / Fail-Safe Safe States).</li>\n<li><strong>Peer-Schnittstellen (gestrichelt):</strong></li>\n<li>Inter-SHM-Kommunikation (<em>Other System Health Monitor(s)</em>) und generische Nicht-AUTOSAR-Domänen (<em>Other platform(s)</em>, z. B. Linux/QNX-Host-OS oder Hypervisor Health).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Lokale Erfassung (Zyklisch / Eventbasiert):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Supervised Entities (SWCs auf CP, Prozesse auf AP) melden Checkpoint-Erreichungen an die lokale Überwachung (<code>WdgM</code> bzw. <code>ara::phm</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Lokale Zustandsbewertung & Sofortmaßnahme:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bestimmung des lokalen Status (<em>Determination of Supervision Status</em>).</li>\n<li>Bei Verletzung: Triggerung von <em>Local Platform Recovery Action</em>. Auf AP: Benachrichtigung an <code>Execution Management</code> zum Prozess-Restart; auf CP: BswM-Regelausführung oder lokaler Watchdog-Timeout.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Meldung an Gesamtsystem (Asynchroner Uplink):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Parallel oder nach Scheitern der lokalen Recovery wird ein <em>Health Indicator + additional Payload</em> über das Kommunikationsnetzwerk an den <em>System Health Manager</em> serialisiert und versendet.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zentrale Systementscheidung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der SHM bewertet alle eingehenden Indikatoren (<em>Determination of Health Indicator(s)</em>) und optionalen Zustände weiterer SHM-Instanzen/Plattformen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>System-Recovery-Kaskade (Downlink Trigger):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>SHM sendet den resultierenden aggregierten <em>Health Indicator</em> / Recovery-Befehl an die betroffenen Plattformen (AP und CP).</li>\n<li>Beide Plattformen triggern synchronisiert ihre jeweiligen Mechanismen zur Systemwiederherstellung (<em>Execution of system Recovery Action</em>), z. B. Umschalten in ein redundantes Fallback-Netzwerk, Degradieren der Fahrfunktion oder koordinierter Systemneustart.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>AP-Entwickler (<code>ara::phm</code>, <code>ara::exec</code>, <code>ara::sm</code>):</strong></li>\n<li><strong>API & Konfiguration:</strong> Checkpoints müssen nach ASWS PHM präzise modelliert werden. Reicht ein lokaler Recovery-Versuch (z. B. <code>RestartProcess</code>) nicht aus oder führt zu Grenzwertüberschreitungen, muss der <code>PHM</code> so konfiguriert sein, dass über AraCom ein Health-Event an den SHM emittiert wird.</li>\n<li>Das <em>State Management</em> muss auf SHM-Payloads reagieren können, um Function Group Transitions (z. B. <code>OffSafe</code>) anzusteuern.</li>\n<li><strong>CP-Entwickler (<code>WdgM</code>, <code>BswM</code>, <code>Com</code>):</strong></li>\n<li><strong>API & Stack-Routing:</strong> Der WdgM-Status (<code>WdgM_GetGlobalStatus</code>) muss über den BswM oder eine System-SWC periodisch/ereignisgesteuert via RTE an den Kommunikationsstack (<code>PduR</code>/<code>SomeIpXf</code>/<code>Com</code>) geroutet werden, um als Payload für den SHM bereitgestellt zu werden.</li>\n<li>System Recovery Actions erfordern vorbereitete BswM-Regelwerke (Action Lists für Shutdown/Reset/Mode Switches via <code>EcuM</code>).</li>\n<li><strong>Systemarchitektur & ASIL-Dekompensation (ISO 26262):</strong></li>\n<li>Die Latenz des Austauschs (<em>Health Indicator + Payload</em>) über Bussysteme begrenzt die erreichbare FTTI (Fault Tolerant Time Interval) für gesamtsystemische Reaktionen.</li>\n<li>Für sicherheitskritische System Recovery Actions müssen End-to-End-Sicherungsmechanismen (E2E-Profile auf Uplink/Downlink) und deterministische Kommunikationskanäle (TSN / deterministisches CAN-FD) verbindlich ausgelegt werden.</li>\n</ul>"}, {"id": "FIG-171aec0cdb4ab92f", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Informelles Block- und Datenflussdiagramm (Architekturübersicht / Functional Flow Block Diagram) zur Darstellung der funktionalen Allokation und des Kontrollflusses.</li>\n<li><strong>Funktionale Einordnung:</strong> AUTOSAR Adaptive Platform (R20-11), Spezifikation <em>ASWS Health Monitoring</em> (gemäß <code>RS_HM_09304</code> – <em>Health information exchange between platforms</em>).</li>\n<li><strong>Technischer Zweck:</strong> Definition der vertikalen und horizontalen Interaktionsmuster zwischen lokalen Plattform-Überwachungsinstanzen (Classic Platform WdgM/BswM vs. Adaptive Platform PHM) und einer übergeordneten, plattformübergreifenden Instanz (<strong>System Health Manager</strong>, SHM). Das Diagramm visualisiert die Trennung von lokaler Fehlerbehandlung (Local Recovery) und koordinierter Gesamtsystem-Reaktion (System Recovery).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>System Health Monitor (SHM):</strong></li>\n<li>Übergeordnete Koordinationsinstanz (zentralisiert oder verteilt ausgeführt).</li>\n<li>Kernfunktion: <em>Determination of Health Indicator(s)</em> – Aggregation und Korrelation plattformspezifischer Gesundheitsindikatoren zu einem konsistenten Systemzustand.</li>\n<li><strong>Adaptive Platform (AP-Instanz):</strong></li>\n<li>Implementiert durch den <em>Platform Health Management</em> (PHM) Dämon und <em>State Management</em> (SM).</li>\n<li>Interne Funktionsblöcke:</li>\n<li><em>Execution of Supervision Functions:</em> Alive-, Deadline- und Logical Supervision über Checkpoints (<code>ara::phm</code>).</li>\n<li><em>Determination of Supervision Status:</em> Aggregation lokaler Checkpoint-Ergebnisse zu <em>Supervision Status</em> / <em>Health Channel Status</em>.</li>\n<li><em>Local Platform Recovery Action:</em> Autonome plattforminterne Aktionen (z. B. Prozess-Neustart via Execution Management <code>ara::exec</code>).</li>\n<li><em>Execution system Recovery Action:</em> Ausführung von Befehlen des SHM (z. B. Function Group State Transitionen).</li>\n<li><strong>Classic Platform (CP-Instanz):</strong></li>\n<li>Implementiert durch <em>Watchdog Manager</em> (<code>WdgM</code>), <em>Basic Software Manager</em> (<code>BswM</code>) und <code>Dem</code>.</li>\n<li>Interne Funktionsblöcke analog zur AP:</li>\n<li><em>Execution of Supervision Functions:</em> Alive-, Deadline- und Logical-Supervision von Supervised Entities (<code>SE</code>).</li>\n<li><em>Determination of Supervision Status:</em> Lokaler/globaler WdgM-Status (<code>WDGM_GLOBAL_STATUS_*</code>).</li>\n<li><em>Local Platform Recovery Action:</em> Lokale Eskalation (z. B. Watchdog-Reset über <code>WdgIf</code>/<code>Wdg</code>, Partition-Restart, BswM-Aktionen).</li>\n<li><em>Execution system Recovery Action:</em> Koordinierte Degradierung (z. B. ECU-Zustandswechsel in <code>EcuM</code>/<code>BswM</code>).</li>\n<li><strong>Schnittstellen & Datenstrukturen:</strong></li>\n<li><strong>Uplink (Plattform $\\rightarrow$ SHM):</strong> <em>Health Indicator + HealthInfo</em></li>\n<li>Übermittlung via fahrzeuginterner Kommunikation (z. B. SOME/IP Events, Ethernet, CAN-FD).</li>\n<li>Signalisiert den lokalen Gesundheitsstatus zuzüglich standardisierter Zusatzinformationen (<code>HealthInfo</code>, z. B. ausgefallene Entity-ID, Fehlercode, Fehlertoleranzzeit/FTTI-Restbudget).</li>\n<li><strong>Downlink (SHM $\\rightarrow$ Plattform):</strong> <em>Health Indicator</em> (bzw. System Action Command)</li>\n<li>Übermittlung an AP und CP zur Einleitung synchronisierter Degradierungsmodi (Fail-Operational / Fail-Safe Safe States).</li>\n<li><strong>Peer-Schnittstellen (gestrichelt):</strong></li>\n<li>Inter-SHM-Kommunikation (<em>Other System Health Monitor(s)</em>) und generische Nicht-AUTOSAR-Domänen (<em>Other platform(s)</em>, z. B. Linux/QNX-Host-OS oder Hypervisor Health).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Lokale Erfassung (Zyklisch / Eventbasiert):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Supervised Entities (SWCs auf CP, Prozesse auf AP) melden Checkpoint-Erreichungen an die lokale Überwachung (<code>WdgM</code> bzw. <code>ara::phm</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Lokale Zustandsbewertung & Sofortmaßnahme:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bestimmung des lokalen Status (<em>Determination of Supervision Status</em>).</li>\n<li>Bei Verletzung: Triggerung von <em>Local Platform Recovery Action</em>. Auf AP: Benachrichtigung an <code>Execution Management</code> zum Prozess-Restart; auf CP: BswM-Regelausführung oder lokaler Watchdog-Timeout.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Meldung an Gesamtsystem (Asynchroner Uplink):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Parallel oder nach Scheitern der lokalen Recovery wird ein <em>Health Indicator + additional Payload</em> über das Kommunikationsnetzwerk an den <em>System Health Manager</em> serialisiert und versendet.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Zentrale Systementscheidung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Der SHM bewertet alle eingehenden Indikatoren (<em>Determination of Health Indicator(s)</em>) und optionalen Zustände weiterer SHM-Instanzen/Plattformen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>System-Recovery-Kaskade (Downlink Trigger):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>SHM sendet den resultierenden aggregierten <em>Health Indicator</em> / Recovery-Befehl an die betroffenen Plattformen (AP und CP).</li>\n<li>Beide Plattformen triggern synchronisiert ihre jeweiligen Mechanismen zur Systemwiederherstellung (<em>Execution of system Recovery Action</em>), z. B. Umschalten in ein redundantes Fallback-Netzwerk, Degradieren der Fahrfunktion oder koordinierter Systemneustart.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>AP-Entwickler (<code>ara::phm</code>, <code>ara::exec</code>, <code>ara::sm</code>):</strong></li>\n<li><strong>API & Konfiguration:</strong> Checkpoints müssen nach ASWS PHM präzise modelliert werden. Reicht ein lokaler Recovery-Versuch (z. B. <code>RestartProcess</code>) nicht aus oder führt zu Grenzwertüberschreitungen, muss der <code>PHM</code> so konfiguriert sein, dass über AraCom ein Health-Event an den SHM emittiert wird.</li>\n<li>Das <em>State Management</em> muss auf SHM-Payloads reagieren können, um Function Group Transitions (z. B. <code>OffSafe</code>) anzusteuern.</li>\n<li><strong>CP-Entwickler (<code>WdgM</code>, <code>BswM</code>, <code>Com</code>):</strong></li>\n<li><strong>API & Stack-Routing:</strong> Der WdgM-Status (<code>WdgM_GetGlobalStatus</code>) muss über den BswM oder eine System-SWC periodisch/ereignisgesteuert via RTE an den Kommunikationsstack (<code>PduR</code>/<code>SomeIpXf</code>/<code>Com</code>) geroutet werden, um als Payload für den SHM bereitgestellt zu werden.</li>\n<li>System Recovery Actions erfordern vorbereitete BswM-Regelwerke (Action Lists für Shutdown/Reset/Mode Switches via <code>EcuM</code>).</li>\n<li><strong>Systemarchitektur & ASIL-Dekompensation (ISO 26262):</strong></li>\n<li>Die Latenz des Austauschs (<em>Health Indicator + Payload</em>) über Bussysteme begrenzt die erreichbare FTTI (Fault Tolerant Time Interval) für gesamtsystemische Reaktionen.</li>\n<li>Für sicherheitskritische System Recovery Actions müssen End-to-End-Sicherungsmechanismen (E2E-Profile auf Uplink/Downlink) und deterministische Kommunikationskanäle (TSN / deterministisches CAN-FD) verbindlich ausgelegt werden.</li>\n</ul>"}], "trans": [{"from": "FIG-794f3df4a8bb388c", "to": "FIG-16b052a715261367", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><strong>System Health Monitor:</strong> Umbenennung des zentralen Blocks von <code>System Health Manager</code> in <code>System Health Monitor</code>.</li>\n<li><strong>Other System Health Monitor(s):</strong> Umbenennung der externen Entität von <code>Other System Health Manager(s)</code> in <code>Other System Health Monitor(s)</code>.</li>\n<li><strong>Uplink-Schnittstelle:</strong> Die an den SHM übertragene Nutzlast von Adaptive Platform und Classic Platform wurde von <code>Health Indicator + additional Payload</code> auf die standardisierte Datenstruktur <code>HealthInfo</code> geändert (<code>Health Indicator + HealthInfo</code>).</li>\n<li><strong>Funktionsblöcke System Recovery:</strong> In beiden Plattform-Blöcken (Adaptive Platform und Classic Platform) wurde die Bezeichnung von <code>Execution of system Recovery Action</code> auf <code>Execution system Recovery Action</code> verkürzt (Wegfall von „of“).</li>\n<li><strong>Classic Platform:</strong> Rahmenfarbe des Classic-Platform-Containers von Orange auf Rot geändert.</li>\n</ul>"}, {"from": "FIG-16b052a715261367", "to": "FIG-171aec0cdb4ab92f", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
